def solve(a):
    def f(x):
        return (x * x - a * a) / (x - a)
    print(f"f(x) = (x**2 - a**2)/(x - a) with a = {a}")
    for h in [0.1, 0.01, 0.001]:
        print(f"  f({a - h}) = {f(a - h):.6f}    f({a + h}) = {f(a + h):.6f}")
    limit = a + a
    print(f"  cancel: f(x) = x + a for x != a, so the limit is a + a = {limit}")
k = int(input())
for i in range(k):
    solve(int(input()))

