import math
def solve(label, f, a):
    print(label)
    for h in [0.1, 0.01, 0.001]:
        print(f"  left f({a - h}) = {f(a - h):.4f}    right f({a + h}) = {f(a + h):.4f}")
    left = round(f(a - 0.000001), 3)
    right = round(f(a + 0.000001), 3)
    print(f"  left limit about {left}, right limit about {right}")
    if left == right:
        print(f"  the sides agree: the limit is about {left}")
    else:
        print("  the sides disagree: no limit")
def jump(x):
    if x < 1:
        return x * x
    return x + 2
def meet(x):
    if x < 2:
        return x * x
    return 2 * x
solve("Case 1 · a step: floor at 2", math.floor, 2)
solve("Case 2 · away from the step: floor at 2.5", math.floor, 2.5)
solve("Case 3 · pieces that jump at 1", jump, 1)
solve("Case 4 · pieces that meet at 2", meet, 2)
solve("Case 5 · a sign function: |x|/x at 0", lambda x: abs(x) / x, 0)

